DROP POLICY IF EXISTS request_access ON public.role_requests;
CREATE POLICY request_access ON public.role_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reviewed_at IS NULL AND requested_role IN ('student','teacher'));
CREATE OR REPLACE FUNCTION public.create_school_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,email) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100),coalesce(NEW.email,'')); IF NEW.raw_user_meta_data->>'requested_role' IN ('student','teacher') THEN INSERT INTO public.role_requests(user_id,requested_role) VALUES(NEW.id,(NEW.raw_user_meta_data->>'requested_role')::public.app_role); END IF; RETURN NEW; END $$;